function Set-PrivacyTweaks {Show-Header;Write-Host "PRIVACIDADE BASICA" -ForegroundColor Yellow;Write-Host "Reduz telemetria suportada, recomendações e Advertising ID.";if(-not(Confirm-WinOptimizerAction "Aplicar ajustes?")){return};try{$d="HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection";$c="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent";$a="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo";New-Item $d,$c,$a -Force|Out-Null;Set-ItemProperty $d AllowTelemetry -Type DWord -Value 1 -Force;Set-ItemProperty $c DisableWindowsConsumerFeatures -Type DWord -Value 1 -Force;Set-ItemProperty $a Enabled -Type DWord -Value 0 -Force;Write-Status "Privacidade basica aplicada. Reinicie o PC." Green;Save-AppliedChange Privacidade "Basica" "Telemetria nivel suportado, Consumer Features e Advertising ID."}catch{Write-Status "Falha parcial." Yellow};Pause-WinOptimizer}
function Reset-PrivacyTweaks {Show-Header;if(-not(Confirm-WinOptimizerAction "Restaurar ajustes de privacidade?")){return};Remove-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" AllowTelemetry -ErrorAction SilentlyContinue;Remove-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent" DisableWindowsConsumerFeatures -ErrorAction SilentlyContinue;New-Item "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo" -Force|Out-Null;Set-ItemProperty "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo" Enabled -Type DWord -Value 1 -Force;Write-Status "Ajustes restaurados. Reinicie o PC." Green;Save-AppliedChange Privacidade "Restaurada" "Politicas removidas.";Pause-WinOptimizer}